package com.vztechcore.vzgallery.ui.components

import android.content.ContentUris
import android.content.Context
import android.net.Uri
import android.os.Build
import android.provider.MediaStore
import android.util.LruCache
import android.util.Size
import androidx.compose.ui.graphics.ImageBitmap
import androidx.compose.ui.graphics.asImageBitmap
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext

/**
 * In-memory cache of video thumbnails.
 *
 * Uses Android's native API (`ContentResolver.loadThumbnail`) which reads
 * the thumbnail already pre-generated by the system — instant, without
 * decoding the whole video.
 */
object VideoThumbCache {

    // ~40MB to fit plenty of thumbnails (~150KB each)
    private val cache = LruCache<String, ImageBitmap>(280)

    suspend fun get(
        context: Context,
        uri: Uri,
        sizePx: Int = 300
    ): ImageBitmap? = withContext(Dispatchers.IO) {
        val key = uri.toString()
        cache.get(key)?.let { return@withContext it }

        val bmp = try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                context.contentResolver.loadThumbnail(
                    uri,
                    Size(sizePx, sizePx),
                    null
                )
            } else {
                // Fallback for Android 9 and below
                val id = ContentUris.parseId(uri)
                MediaStore.Video.Thumbnails.getThumbnail(
                    context.contentResolver,
                    id,
                    MediaStore.Video.Thumbnails.MINI_KIND,
                    null
                )
            }
        } catch (e: Exception) {
            null
        }

        bmp?.asImageBitmap()?.also { cache.put(key, it) }
    }
}